import time

# from <your_acme_sdk> import RateLimitError  # import path not confirmed in docs; name per v3 errors page

DEFAULT_BACKOFF_S = 0.5  # v3 default retry backoff (500 ms)

def call_with_retry(do_request):
    try:
        return do_request()
    except RateLimitError as err:
        delay = getattr(err, "retry_after_seconds", None)
        if delay is None:
            delay = DEFAULT_BACKOFF_S
        time.sleep(delay)
        return do_request()
